package br.com.tapeteskalke.service; import br.com.tapeteskalke.exception.AccessDeniedBusinessException; import br.com.tapeteskalke.repository.PermissaoRepository; import br.com.tapeteskalke.security.Cargos; import br.com.tapeteskalke.security.CurrentUser; import java.util.*; import org.springframework.stereotype.Service;
// O ADMINISTRADOR tem todas as páginas e ações sempre liberadas (inclusive as que forem criadas no futuro); os demais cargos seguem a tabela.
@Service public class PermissionService { private final CurrentUser current; private final PermissaoRepository permissions; public static final List<String> PAGES=List.of("dashboard","clientes","funcionarios","reativacao","produtos","vendas","compras","fornecedores","producao","entregas","despesas","relatorios","configuracoes"); public static final List<String> ACTIONS=List.of("clientes_criar","clientes_editar","clientes_excluir","produtos_criar","produtos_editar","produtos_excluir","produtos_imagens","portfolio_publicar","mensagens_gerenciar","reativacao_gerenciar","clientes_consentimento","vendas_criar","vendas_cancelar","compras_criar","compras_cancelar","producao_criar","producao_finalizar","producao_cancelar","despesas_criar","despesas_editar","despesas_excluir","estoque_ajustar","entregas_criar","entregas_atualizar_status","funcionarios_criar","funcionarios_editar","funcionarios_excluir","relatorios_visualizar","configuracoes_editar"); public PermissionService(CurrentUser current,PermissaoRepository permissions){this.current=current;this.permissions=permissions;}
 private boolean temPagina(String role,String page){return Cargos.ADMINISTRADOR.equals(role)||permissions.hasPage(role,page);}
 private boolean temAcao(String role,String action){return Cargos.ADMINISTRADOR.equals(role)||permissions.hasAction(role,action);}
 public void action(String action){var u=current.require();if(!temAcao(u.role(),action))throw new AccessDeniedBusinessException("Sem permissão para: "+action);} public void page(String page){var u=current.require();if(!temPagina(u.role(),page))throw new AccessDeniedBusinessException("Sem acesso à página: "+page);} public Map<String,Boolean> pages(){return pagesFor(current.require().role());} public Map<String,Boolean> actions(){return actionsFor(current.require().role());} public Map<String,Boolean> pagesFor(String role){var r=new LinkedHashMap<String,Boolean>();for(var p:PAGES)r.put(p,temPagina(role,p));return r;} public Map<String,Boolean> actionsFor(String role){var r=new LinkedHashMap<String,Boolean>();for(var a:ACTIONS)r.put(a,temAcao(role,a));return r;} }
